"""Inline quality workbench for source checks and limited review declarations."""
HTML='''<details id="so-quality-panel" class="so-step so-evaluation"><summary>REVISAR MOVIMIENTOS, COBERTURA Y SALDO INICIAL</summary><p>Contrasta los registros y conserva las revisiones documentales sin salir de la propuesta. Las coincidencias técnicas y las declaraciones humanas se muestran por separado.</p><button id="so-quality-load" type="button">Comprobar las fuentes actuales</button><p id="so-quality-status" class="st-state" role="status"></p><div id="so-quality-summary" class="so-advice-grid"></div>
<section class="st-stage"><h3>1 · Movimientos y soportes</h3><label>Mostrar<select id="so-quality-filter"><option value="ISSUES">Discrepancias y pendientes</option><option value="ALL">Todos los movimientos</option><option value="DISCREPANCY">Solo discrepancias</option><option value="PENDING">Solo pendientes</option><option value="MATCHED">Coincidencias técnicas</option><option value="DECLARED_REVIEWED">Revisiones declaradas</option></select></label><p id="so-quality-count"></p><div class="scroll"><table><thead><tr><th>Movimiento / vencimiento</th><th>Importe</th><th>Resultado y motivo</th><th>Consultar / revisar</th></tr></thead><tbody id="so-quality-rows"></tbody></table></div>
<details id="so-quality-editor"><summary>Asociar un soporte y registrar su revisión</summary><p>Utiliza esta opción cuando hayas contrastado el documento. No sustituye la corrección de importes o fechas discrepantes.</p><label>Movimiento<select id="so-quality-flow"></select></label><label>Buscar soporte<input id="so-quality-query" type="search" placeholder="Archivo, factura, referencia de cuota o cliente"></label><label>Soporte comprobado<select id="so-quality-support"></select></label><button id="so-quality-view-support" type="button">Ver soporte seleccionado</button><label>Qué has comprobado<textarea id="so-quality-link-note" rows="3" maxlength="1000"></textarea></label><button id="so-quality-add-link" type="button">Añadir asociación a la revisión</button><div id="so-quality-links"></div></details>
<details id="so-quality-source-panel"><summary>Fila o soporte consultado</summary><p id="so-quality-source-title"></p><div id="so-quality-source-data"></div><button id="so-quality-download" type="button" hidden>Descargar documento original</button></details></section>
<section class="st-stage"><h3>2 · Cobertura del calendario</h3><p>Indica el periodo revisado. Tener movimientos vinculados no demuestra que estén incluidos todos los cobros y pagos pendientes.</p><div id="so-quality-gaps"></div><label>Resultado de la revisión<select id="so-quality-coverage"><option value="NOT_REVIEWED">Sin revisar</option><option value="DECLARED_INCOMPLETE">Revisado · cobertura incompleta</option><option value="DECLARED_COMPLETE">Revisado · declaro cobertura completa del periodo</option></select></label><label>Periodo: desde el corte hasta<input id="so-quality-until" type="date"></label><label>Fuentes que fundamentan esta revisión<select id="so-quality-coverage-sources" multiple size="5"></select></label></section>
<section class="st-stage"><h3>3 · Contrastar el saldo inicial</h3><p>Introduce el saldo que has leído en el extracto o arqueo independiente. No se rellena copiando el saldo contable. EIOS comparará ambos importes; la lectura del soporte quedará como declaración.</p><div id="so-quality-accounts"></div></section>
<section class="st-stage"><h3>4 · Conservar la revisión</h3><div class="fields"><label>Responsable<input id="so-quality-actor" maxlength="1000"></label><label>Conclusión y observaciones<textarea id="so-quality-note" rows="3" maxlength="1000"></textarea></label></div><label class="st-check"><input id="so-quality-ack" type="checkbox"><span>Confirmo que he realizado las comprobaciones que registro sobre este expediente sintético. Las declaraciones no acreditan validación formal de calidad, cobro, pago ni autorización de la venta.</span></label><button id="so-quality-save" type="button" class="primary">Guardar revisión documental</button><p id="so-quality-notice" role="status"></p><details><summary>Historial de revisiones</summary><div id="so-quality-history"></div></details></section></details>'''
JS=r'''
let salesQualityReport=null,salesQualityDataset=null,salesQualityVersion=0,salesQualityLinks=new Map(),salesQualityDownloadSource=null;
async function openSalesQuality(){const panel=$('so-quality-panel');panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});await loadSalesQuality()}
async function loadSalesQuality(){const dataset=$('dataset').value,seq=++salesQualityVersion;$('so-quality-status').textContent='Comprobando las fuentes actuales…';$('so-quality-save').disabled=true;try{const r=await api('/api/sales-proposals/quality/read',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset})});if(dataset!==$('dataset').value||seq!==salesQualityVersion)return;salesQualityReport=r;salesQualityDataset=dataset;salesQualityLinks=new Map((r.review?.movement_links||[]).map(x=>[x.flow_id,x]));$('so-quality-status').textContent='Corte '+stockDate(r.as_of_date)+' · '+(r.review_status==='CURRENT'?'Revisión registrada para estas fuentes':r.review_status==='STALE'?'Las fuentes han cambiado: la revisión anterior se conserva como histórica':'Sin revisión documental registrada')+'. Los movimientos conservan su estado de evidencia original.';$('so-quality-summary').replaceChildren();salesAdviceMetrics($('so-quality-summary'),[['Movimientos',r.summary.total],['Coincidencias técnicas',r.summary.matched],['Discrepancias',r.summary.discrepancies],['Sin contraste',r.summary.pending]]);$('so-quality-flow').replaceChildren();option($('so-quality-flow'),'','Selecciona un movimiento');r.rows.slice(0,2000).forEach(x=>option($('so-quality-flow'),x.flow_id,x.flow_id+' · '+money(x.amount)+' '+x.currency));$('so-quality-query').value='';renderSalesQualitySources();renderSalesQualityRows();renderSalesQualityLinks();renderSalesQualityAccounts();$('so-quality-coverage').value=r.coverage;$('so-quality-until').value=r.review?.coverage_until||'';for(const o of $('so-quality-coverage-sources').options)o.selected=(r.review?.coverage_sources||[]).includes(o.value);$('so-quality-actor').value=r.review?.actor||'';$('so-quality-note').value=r.review?.note||'';$('so-quality-ack').checked=false;$('so-quality-gaps').replaceChildren();const gapNote=document.createElement('p');gapNote.textContent=r.quota_gaps.length?r.quota_gaps.length+' referencias de cuota con pendiente positivo o desconocido no se han localizado inequívocamente en la previsión. Revisa las fechas y filas antes de declarar cobertura completa.':'No se detectan cuotas sin referencia en la previsión dentro de las fuentes disponibles. Esto no acredita cobertura global.';$('so-quality-gaps').append(gapNote);r.quota_gaps.slice(0,100).forEach(g=>{const b=document.createElement('button');b.type='button';b.textContent=g.reference+' · '+stockDate(g.due_date)+' · '+(g.pending_amount===null?'Pendiente desconocido':money(g.pending_amount)+' EUR');b.onclick=()=>showSalesQualitySource(r.sources.find(s=>s.source_id===g.source_id));$('so-quality-gaps').append(b)});receptionTable('so-quality-history',['Revisión','Responsable','Fecha','Cobertura declarada','Soportes'],(r.history||[]).map(h=>[h.revision,h.actor,stockDate(h.created_at),({DECLARED_COMPLETE:'Completa para el periodo declarado',DECLARED_INCOMPLETE:'Incompleta',NOT_REVIEWED:'Sin revisar'})[h.coverage],Object.values(h.source_refs||{}).map(x=>x.source.filename+' · '+(x.source.sheet||'')+' · fila '+(x.source.row??'—')).join(' | ')]));$('so-quality-notice').textContent=(r.invalid_sources||[]).length?'Hay soportes con integridad no coincidente: '+r.invalid_sources.join(' · '):''}catch(e){if(dataset===$('dataset').value&&seq===salesQualityVersion)$('so-quality-status').textContent=e.message}finally{if(dataset===$('dataset').value&&seq===salesQualityVersion)$('so-quality-save').disabled=!salesQualityReport||salesQualityDataset!==dataset}}
function qualitySourceText(s){const d=s.data;return s.source.filename+' · '+(s.source.sheet||'')+' · fila '+(s.source.row??'—')+' · '+(d.invoice_number||d.installment_ref||d.document_ref||s.source.record_id||'')}
function renderSalesQualitySources(){const r=salesQualityReport;if(!r)return;const query=$('so-quality-query').value.toLocaleLowerCase('es'),previous=$('so-quality-support').value,sources=r.sources.filter(s=>['document','sales_installment','purchase_installment','sales_line','purchase_line'].includes(s.kind)&&qualitySourceText(s).toLocaleLowerCase('es').includes(query));$('so-quality-support').replaceChildren();option($('so-quality-support'),'','Selecciona un soporte · '+sources.length+' resultados, se muestran hasta 200');sources.slice(0,200).forEach(s=>option($('so-quality-support'),s.source_id,qualitySourceText(s)));if([...$('so-quality-support').options].some(o=>o.value===previous))$('so-quality-support').value=previous;const select=$('so-quality-coverage-sources'),selected=new Set([...select.selectedOptions].map(o=>o.value));select.replaceChildren();r.sources.slice(0,500).forEach(s=>{option(select,s.source_id,qualitySourceText(s));select.lastElementChild.selected=selected.has(s.source_id)})}
function renderSalesQualityRows(){const r=salesQualityReport,filter=$('so-quality-filter').value,rows=r.rows.filter(x=>filter==='ALL'||filter==='ISSUES'?filter==='ALL'||['PENDING','DISCREPANCY'].includes(x.status):x.status===filter),body=$('so-quality-rows');body.replaceChildren();$('so-quality-count').textContent=rows.length+' resultados · mostrando '+Math.min(rows.length,500)+' · '+r.summary.total+' movimientos en total.';const names={MATCHED:'Coinciden los registros',DISCREPANCY:'Discrepancia',PENDING:'Pendiente de contraste',DECLARED_REVIEWED:'Revisión declarada'};rows.slice(0,500).forEach(x=>{const tr=document.createElement('tr');salesCells(tr,[x.flow_id+' · '+x.direction+' · '+stockDate(x.due_date),x.amount===null?'Sin importe':money(x.amount)+' '+x.currency,names[x.status]+' · '+x.message]);const actions=document.createElement('td');if(x.source){const view=document.createElement('button');view.type='button';view.textContent='Ver fila de origen';view.onclick=()=>showSalesQualitySource({source:x.source,data:x.source.data});actions.append(view)}x.support_ids.slice(0,3).forEach(id=>{const view=document.createElement('button');view.type='button';view.textContent='Ver cuota vinculada';view.onclick=()=>showSalesQualitySource(r.sources.find(s=>s.source_id===id));actions.append(view)});const link=document.createElement('button');link.type='button';link.textContent='Asociar soporte';link.onclick=()=>{$('so-quality-editor').open=true;$('so-quality-flow').value=x.flow_id;$('so-quality-link-note').value=salesQualityLinks.get(x.flow_id)?.note||'';$('so-quality-editor').scrollIntoView({behavior:'smooth',block:'start'})};actions.append(link);tr.append(actions);body.append(tr)})}
function renderSalesQualityLinks(){const box=$('so-quality-links');box.replaceChildren();salesQualityLinks.forEach((link,id)=>{const p=document.createElement('p');p.textContent=id+' · '+link.note;const remove=document.createElement('button');remove.type='button';remove.textContent='Retirar asociación del borrador';remove.onclick=()=>{salesQualityLinks.delete(id);renderSalesQualityLinks()};p.append(remove);box.append(p)})}
function showSalesQualitySource(item){if(!item)return;$('so-quality-source-panel').open=true;$('so-quality-source-title').textContent=item.source.filename+' · '+(item.source.sheet||'')+' · fila '+(item.source.row??'—');const labels={flow_id:'Referencia del movimiento',direction:'Cobro o pago',amount:'Importe',currency:'Moneda',due_date:'Vencimiento',customer_id:'Código de cliente',supplier_id:'Código de proveedor',invoice_number:'Factura',installment_ref:'Referencia de cuota',pending_amount:'Pendiente al corte',pending:'Pendiente al corte',balance:'Saldo',account_code:'Cuenta',payment_method:'Forma de pago',net_amount:'Importe neto',issue_date:'Fecha de factura',original_due_date:'Vencimiento original',revised_due_date:'Vencimiento revisado',description:'Descripción',support_ref:'Referencia de soporte',support_type:'Tipo de soporte'};receptionTable('so-quality-source-data',['Campo','Valor'],Object.entries(item.data||{}).map(([k,v])=>[labels[k]||k,v!==null&&typeof v==='object'?JSON.stringify(v):v??'Sin dato']));salesQualityDownloadSource=item.source;$('so-quality-download').hidden=!item.source.batch_id||!item.source.company_id;$('so-quality-source-panel').scrollIntoView({behavior:'smooth',block:'start'})}
function renderSalesQualityAccounts(){const r=salesQualityReport,box=$('so-quality-accounts');box.replaceChildren();if(!r.accounts.length){salesAdviceNote(box,'No hay un desglose de cuentas seleccionado para contrastar. Revisa primero las fuentes de caja y bancos.',true);return}const supports=r.sources.filter(s=>['document','bank_statement_entry','cash_count','treasury_balances'].includes(s.kind));r.accounts.forEach(a=>{const section=document.createElement('section');section.className='so-line-conditions';section.dataset.qualityAccount=a.account_code;const h=document.createElement('h4');h.textContent='Cuenta '+a.account_code+' · Saldo contable '+money(a.balance)+' EUR';section.append(h);salesAdviceNote(section,a.status==='DECLARED_MATCH'?'El saldo observado declarado coincide con el contable. Lectura del soporte no verificada automáticamente.':a.status==='DIFFERENCE'?'Hay una diferencia entre el saldo contable y el observado. Revisa la conciliación.':'Sin observación de un soporte independiente.');const select=document.createElement('select');select.dataset.quality='source_id';option(select,'','Selecciona extracto, arqueo o soporte independiente');supports.slice(0,500).forEach(s=>option(select,s.source_id,qualitySourceText(s)));select.value=a.observation?.source_id||'';const label=document.createElement('label');label.textContent='Soporte independiente';label.append(select);section.append(label);const balance=document.createElement('input');balance.inputMode='decimal';balance.dataset.quality='observed_balance';balance.value=a.observation?stockNumber(a.observation.observed_balance):'';balance.placeholder='Saldo leído en el soporte';const bl=document.createElement('label');bl.textContent='Saldo observado en EUR';bl.append(balance);section.append(bl);const view=document.createElement('button');view.type='button';view.textContent='Ver soporte de esta cuenta';view.onclick=()=>showSalesQualitySource(r.sources.find(s=>s.source_id===select.value));section.append(view);box.append(section)})}
$('so-quality-panel').addEventListener('input',event=>event.stopPropagation());$('so-quality-panel').addEventListener('change',event=>event.stopPropagation());
$('so-quality-load').onclick=loadSalesQuality;$('so-quality-filter').onchange=()=>{if(salesQualityReport)renderSalesQualityRows()};$('so-quality-query').oninput=renderSalesQualitySources;$('so-quality-view-support').onclick=()=>showSalesQualitySource(salesQualityReport?.sources.find(s=>s.source_id===$('so-quality-support').value));
$('so-quality-add-link').onclick=()=>{const id=$('so-quality-flow').value,source=$('so-quality-support').value,note=$('so-quality-link-note').value.trim();if(!id||!source||!note){$('so-quality-notice').textContent='Selecciona movimiento, soporte y explica qué has contrastado.';return}salesQualityLinks.set(id,{flow_id:id,source_id:source,note});renderSalesQualityLinks();$('so-quality-notice').textContent='Asociación añadida al borrador. Guarda la revisión para conservarla.'};
$('so-quality-download').onclick=async()=>{const s=salesQualityDownloadSource;if(!s?.batch_id)return;try{const response=await fetch('/api/reception/original',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({company_id:s.company_id,batch_id:s.batch_id})});if(!response.ok)throw Error('No se puede descargar el soporte original.');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=s.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){$('so-quality-notice').textContent=e.message}};
$('so-quality-save').onclick=async()=>{const dataset=$('dataset').value,seq=salesQualityVersion,version=salesOfferVersion,r=salesQualityReport;if(!r||salesQualityDataset!==dataset){$('so-quality-notice').textContent='Comprueba primero las fuentes de esta empresa.';return}const button=$('so-quality-save');button.disabled=true;invalidateSalesProposal();try{const observations=[...$('so-quality-accounts').querySelectorAll('[data-quality-account]')].map(section=>({account_code:section.dataset.qualityAccount,source_id:section.querySelector('[data-quality=source_id]').value,observed_balance:parameterNumber(section.querySelector('[data-quality=observed_balance]').value),currency:'EUR',as_of_date:r.as_of_date})).filter(x=>x.source_id||x.observed_balance!=='');await api('/api/sales-proposals/quality/save',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,basis_fingerprint:r.basis_fingerprint,revision:r.review_revision,actor:$('so-quality-actor').value.trim(),note:$('so-quality-note').value.trim(),acknowledge:$('so-quality-ack').checked,movement_links:[...salesQualityLinks.values()],account_observations:observations,coverage:$('so-quality-coverage').value,coverage_until:$('so-quality-until').value||null,coverage_sources:[...$('so-quality-coverage-sources').selectedOptions].map(o=>o.value)})});const updated=await api('/api/state?dataset='+encodeURIComponent(dataset));if(dataset!==$('dataset').value||seq!==salesQualityVersion||version!==salesOfferVersion)return;state=updated;invalidateSalesProposal();await loadSalesQuality();$('so-quality-notice').textContent='Revisión conservada con sus fuentes. Evalúa de nuevo la propuesta; la evidencia financiera no se ha promovido automáticamente.'}catch(e){if(dataset===$('dataset').value)$('so-quality-notice').textContent=e.message}finally{if(dataset===$('dataset').value)button.disabled=false}};
'''
CSS='''#so-quality-panel .scroll{max-height:520px;overflow:auto}#so-quality-panel table{min-width:700px;width:100%}#so-quality-panel td{white-space:normal;overflow-wrap:anywhere;vertical-align:top}#so-quality-panel th{position:sticky;top:0;background:#173e77;color:white;z-index:1}#so-quality-panel td:nth-child(3){min-width:220px}#so-quality-panel .so-advice-grid{display:block}#so-quality-panel select[multiple]{min-height:150px}#so-quality-panel [data-quality-account]{margin:18px 0;padding:18px}#so-quality-panel details{margin-top:20px;border-top:1px solid #d2dce6;padding-top:12px}.so-check-info{border-left:5px solid #6386aa;background:#f0f5fc}.so-check-info>strong{color:#355b83}'''
